begin read only;
with e as(select * from public._m029_recovery_expected),tline as(select count(*) n,max(id) max_id,encode(extensions.digest(coalesce(string_agg(id::text||':'||object_id::text||':'||event_type,',' order by id),''),'sha256'),'hex') h from public.operational_activity_events where owner_user_id=(select owner_user_id from e)),p as(select e.*,exists(select 1 from public.clients where id=e.client_id and workspace_id=e.workspace_id and data_owner_id=e.owner_user_id) client_ok,exists(select 1 from public.opportunities where id=e.application_id and workspace_id=e.workspace_id and created_by=e.owner_user_id) application_ok,exists(select 1 from public.campaigns where id=e.goal_id and workspace_id=e.workspace_id and data_owner_id=e.owner_user_id) goal_ok,exists(select 1 from public.tasks where id=e.work_id and workspace_id=e.workspace_id and data_owner_id=e.owner_user_id and version=e.work_version and status='cancelled') work_ok,exists(select 1 from public.personal_operational_records where id=e.content_id and workspace_id=e.workspace_id and data_owner_id=e.owner_user_id and version=e.content_version) content_ok,exists(select 1 from public.business_memory_records where id=e.knowledge_id and workspace_id=e.workspace_id and data_owner_id=e.owner_user_id) knowledge_ok,exists(select 1 from public.operational_objects where id=e.quick_capture_id and workspace_id=e.workspace_id and owner_user_id=e.owner_user_id) capture_ok,exists(select 1 from public.personal_operational_records where id=e.converted_content_id and workspace_id=e.workspace_id and data_owner_id=e.owner_user_id) converted_ok,exists(select 1 from public.canonical_domain_drafts where owner_user_id=e.owner_user_id and workspace_id=e.workspace_id and object_id=e.content_id and draft_version=e.draft_version and base_object_version=e.content_version) draft_ok,exists(select 1 from public.canonical_domain_conversions where id=e.conversion_id and owner_user_id=e.owner_user_id and workspace_id=e.workspace_id and source_id=e.quick_capture_id and target_id=e.converted_content_id) conversion_ok,exists(select 1 from public.operational_object_links where id=e.link_id and owner_user_id=e.owner_user_id and workspace_id=e.workspace_id) link_ok from e)
select jsonb_build_object('result',case when client_ok and application_ok and goal_ok and work_ok and content_ok and knowledge_ok and capture_ok and converted_ok and draft_ok and conversion_ok and link_ok and t.n=p.timeline_count and t.max_id=p.timeline_max_id and t.h=p.timeline_hash then 'M029_RECOVERY_REIMPORT_PASS' else 'FAIL' end,'objects_preserved',(client_ok::int+application_ok::int+goal_ok::int+work_ok::int+content_ok::int+knowledge_ok::int+capture_ok::int+converted_ok::int),'ownership_workspace',client_ok and application_ok and goal_ok and work_ok and content_ok and knowledge_ok,'versions',work_ok and content_ok,'draft_base',draft_ok,'timeline_identity',t.n=p.timeline_count and t.max_id=p.timeline_max_id and t.h=p.timeline_hash,'links',link_ok,'conversion_identity',conversion_ok,'archive_state',work_ok) verification from p cross join tline t;
rollback;
